    /// <summary>What it does each time its own timer fires.</summary>
    internal static PatternBranch[] OnIdleTimerFor(int npcId)
        => OnIdleTimer.TryGetValue(npcId, out PatternBranch[]? rungs) ? rungs : [];

    private static readonly IReadOnlyDictionary<int, PatternBranch[]> OnIdleTimer =
        BuildOnIdleTimer();

    private static Dictionary<int, PatternBranch[]> BuildOnIdleTimer()
    {
        Dictionary<int, PatternBranch[]> rungs = new Dictionary<int, PatternBranch[]>();
        OnIdleTimer0(rungs);
        OnIdleTimer1(rungs);
        OnIdleTimer2(rungs);
        OnIdleTimer3(rungs);
        return rungs;
    }

